namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalTests
{
    private readonly CalculatePayableTotal _useCase;

    public CalculatePayableTotalTests()
    {
        var loyaltyDiscountPolicy = new LoyaltyDiscountPolicy();
        _useCase = new CalculatePayableTotal(loyaltyDiscountPolicy);
    }

    [Theory]
    [InlineData(10_000, 9_500)]
    [InlineData(20_000, 19_000)]
    [InlineData(5_000, 4_750)]
    [InlineData(0, 0)]
    public void Gold_tier_pays_95_percent_of_subtotal(int subtotalCents, int expectedPayableTotalCents)
    {
        var actualPayableTotalCents = _useCase.For(subtotalCents, LoyaltyTier.Gold);

        Assert.Equal(expectedPayableTotalCents, actualPayableTotalCents);
    }
}
''')
